// Resumo legível no celular: a resposta crua da API é grande demais para
// ler na tela do formulário.
const r = $json || {};
const d = r.data || {};
const linhas = [];

if (r.success === false) {
  linhas.push('ERRO: ' + (r.error || 'falha desconhecida'));
  if (r.details) linhas.push(String(r.details).slice(0, 300));
} else if (d.maneuver || d.exam) {
  const m = d.maneuver || d.exam;
  linhas.push('Preview gerado (NAO escreveu no Notion)');
  linhas.push('Item: ' + (m.name || '-'));
  linhas.push('Categoria: ' + (m.category || '-'));
  linhas.push('Trava: ' + m.automation_status + ' / ' + m.review_status);
  linhas.push('');
  if (d.exam) {
    linhas.push('Quando pedir: ' + (m.when_to_request || '(vazio)'));
    linhas.push('');
    linhas.push('Como interpretar: ' + (m.how_to_interpret || '(vazio)'));
    linhas.push('');
    linhas.push('Limitacoes: ' + (m.limitations || '(vazio)'));
  } else {
    linhas.push('Quando fazer: ' + (m.when_to_perform || '(vazio)'));
    linhas.push('');
    linhas.push('Como executar: ' + (m.how_to_perform || '(vazio)'));
    linhas.push('');
    linhas.push('Achado positivo: ' + (m.positive_finding || '(vazio)'));
  }
} else if (Array.isArray(d.results)) {
  linhas.push(d.dryRun ? 'SIMULACAO (nada foi escrito)' : 'Automacao executada');
  linhas.push('Encontradas: ' + d.found + ' | geradas: ' + d.generated + ' | corrigidas: ' + d.corrected + ' | erros: ' + d.errors);
  for (const x of d.results) {
    linhas.push((x.ok ? 'OK' : 'ERRO') + ' - ' + x.action + ': ' + (x.titulo || '-') + ' -> ' + (x.newStatusAutomacao || x.error || ''));
  }
  if (d.processed === 0) linhas.push('(nenhuma linha marcada "a gerar" ou "a corrigir")');
} else if (Array.isArray(d.items)) {
  linhas.push('Fila de manobras incompletas');
  linhas.push('Publicadas: ' + d.totalPublished + ' | incompletas: ' + d.totalIncomplete + ' | enfileiradas: ' + d.queued);
  for (const x of d.items) {
    linhas.push('- ' + (x.name || '-') + ' (faltando: ' + (x.missingFields || []).join(', ') + ')');
  }
  if (d.totalIncomplete === 0) linhas.push('Nenhuma manobra publicada com campo vazio.');
} else if (d.totalFromNotion !== undefined) {
  linhas.push('Sync Notion -> site');
  linhas.push('Sincronizadas: ' + d.persisted + '/' + d.totalFromNotion + ' | publicadas: ' + d.publishedAvailable);
  const retidas = d.held || [];
  if (retidas.length) {
    linhas.push('Retidas (aguardando revisao humana):');
    for (const x of retidas) linhas.push('- ' + (x.name || '-') + ' (' + x.automationStatus + ')');
  }
  const puladas = d.skipped || [];
  for (const x of puladas) {
    linhas.push('PULADA: ' + (x.name || '-') + ' -> ' + (x.reasons || []).join(', '));
  }
} else {
  linhas.push(JSON.stringify(r).slice(0, 500));
}

return [{ json: { resultado: linhas.join('\n') } }];
